import {UUID,normalizeNotice} from './notice-contract.js?v=321';
import {activatePushDevice} from './push-device.js?v=323';
import {NoticeAttention} from './notice-attention.js?v=322';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const newId=()=>globalThis.crypto.randomUUID?.()||'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16));
const ROOT=new URL('./',import.meta.url),DRAFT='cris:notice:draft:';
const icon='<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>';
export const occurrenceExample=()=>({title:'Nova ocorrência — Paris',summary:'Possível suicídio registrado. Equipes policiais no local. Relatório preliminar disponível.',code:'010',date:'2026-10-07',occurrenceTime:'',address:'Edifício nº 113, ao lado do Café des Lilas\nPorte de Montreuil · Paris, 20º arrondissement',location:'Paris, França',nature:'Morte suspeita',situation:'Local isolado',preliminary:'Uma morte com suspeita inicial de suicídio foi registrada em um edifício residencial na região de Porte de Montreuil, Paris.\n\nEquipes policiais permanecem no local. A identificação da vítima e as circunstâncias da morte ainda estão sendo apuradas.',guidance:'Ocorrência ativa. Recomenda-se avaliação da equipe responsável enquanto o local permanece preservado.',imagePath:'',imageCaption:'Imagem da ocorrência · Fonte: autoridades locais'});
export function prepareNoticeDraft(stored){const example=occurrenceExample();if(!stored)return example;const legacy=stored.preliminary==='Uma morte com suspeita inicial de suicídio foi registrada nas proximidades de um estabelecimento comercial em Paris.\n\nEquipes policiais permanecem no local. A identificação da vítima e as circunstâncias da morte ainda estão sendo apuradas.';const result={...example,...stored,occurrenceTime:stored.occurrenceTime||'',address:stored.address??(legacy?example.address:'')};if(legacy){result.preliminary=example.preliminary;if(stored.code==='013')result.code=example.code;}return result;}
export function occurrenceMarkup(p,{imageURL='',test=false}={}){
 const date=/^\d{4}-\d{2}-\d{2}$/.test(p.date||'')?p.date.split('-').reverse().join('/'):'Data a confirmar',generic=test&&p.previewKind!=='draft';
 return `<article class="notice-report">${test?'<div class="notice-private-label">TESTE PRIVADO · VISÍVEL SOMENTE PARA VOCÊ</div>':''}<header><div><span>ORDO REALITAS / CRIS · CENTRAL DE OPERAÇÕES</span><h2>${generic?'TESTE DO CANAL':'OCORRÊNCIA '+esc(p.code)}</h2><p>${esc(date)} · ${esc(p.occurrenceTime||'Horário a confirmar')}${p.occurrenceTime?' (Paris)':''}</p><p class="notice-city">${esc(p.location)}</p></div><b>${test?'Somente você':'Em andamento'}</b></header><section class="notice-address"><h3>LOCAL DA OCORRÊNCIA</h3><p>${esc(p.address||'Endereço a confirmar')}</p></section>${imageURL?`<figure><div class="notice-report-label">REGISTRO FOTOGRÁFICO</div><a href="${esc(imageURL)}" target="_blank" rel="noopener"><img src="${esc(imageURL)}" alt="Fotografia da ocorrência"></a><figcaption>${esc(p.imageCaption)}</figcaption></figure>`:'<div class="notice-no-photo">Registro fotográfico não anexado</div>'}<dl><div><dt>NATUREZA</dt><dd>${esc(p.nature)}</dd></div><div><dt>SITUAÇÃO</dt><dd>${esc(p.situation)}</dd></div></dl><section><h3>Informações preliminares</h3><p>${esc(p.preliminary)}</p></section><section class="notice-guidance"><h3>Orientação operacional</h3><p>${esc(p.guidance)}</p></section></article>`;
}
export async function mountNotifications({bridge,identity,anchor,client:providedClient}={}){
 if(!identity||document.querySelector('#crisNotificationButton'))return;
 if(!document.querySelector('link[href*="notifications.css"]')){const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('notifications.css?v=328',ROOT);document.head.append(css);}
 const client=providedClient||await (await import(new URL('cloud-account.js',bridge.directorURL))).getCloudClient(),campaign=bridge.campaignId;
 let alive=true,notices=[],read=new Set(),known=new Set(),first=true,loading=false,mode='inbox',draft=occurrenceExample(),requestId=newId(),sending=false,photo='',lastTrigger;
 try{const stored=JSON.parse(localStorage.getItem(DRAFT+identity.userId+':'+campaign)||'null');if(stored){draft=prepareNoticeDraft(stored);if(UUID.test(stored._requestId||''))requestId=stored._requestId;}}catch{}
 const button=document.createElement('button');button.id='crisNotificationButton';button.type='button';button.className='cris-notification-trigger';button.innerHTML=icon+'<span>Notificações</span><b hidden>0</b>';button.setAttribute('aria-label','Notificações');(anchor||document.querySelector('.topbar')||document.body).append(button);
 const dialog=document.createElement('dialog');dialog.className='cris-notifications';dialog.setAttribute('aria-labelledby','noticesTitle');dialog.innerHTML=`<header class="notices-head"><div><span>C.R.I.S. / CENTRAL DE OPERAÇÕES</span><h2 id="noticesTitle">Notificações</h2></div><button type="button" data-close aria-label="Fechar notificações">✕</button></header><nav class="notices-tabs"><button type="button" data-mode="inbox">Recebidas</button>${identity.isMaster?'<button type="button" data-mode="compose">Nova ocorrência</button>':''}<button type="button" data-mode="device">Este aparelho</button></nav><p class="notices-status" role="status" aria-live="polite"></p><div class="notices-body"></div>`;document.body.append(dialog);
 const body=dialog.querySelector('.notices-body'),status=dialog.querySelector('[role=status]'),baseTitle=document.title,attention=new NoticeAttention({userId:identity.userId});
 const unlockAudio=()=>{if(!attention.ready)attention.unlock();};document.addEventListener('pointerdown',unlockAudio,true);document.addEventListener('keydown',unlockAudio,true);
 let setupBanner=null,setupDismissed=false;
 const say=(text,error=false)=>{if(!alive)return;status.textContent=text;status.dataset.error=String(error);};
 const call=async(action,values={})=>{const r=await client.functions.invoke('cris-notifications',{body:{action,...values}});if(r.error){let message;try{message=(await r.error.context.json()).error;}catch{}throw Error(message||'Não foi possível conectar ao canal de notificações.');}if(r.data?.error)throw Error(r.data.error);return r.data;};
 const setMode=next=>{if(sending)return;mode=next;status.textContent='';dialog.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===next)));if(next==='compose')renderCompose();else if(next==='device')renderDevice();else renderInbox();};
 const close=()=>{if(sending)return;dialog.close();lastTrigger?.focus();};dialog.querySelector('[data-close]').onclick=close;dialog.addEventListener('cancel',e=>{if(sending)e.preventDefault();});dialog.addEventListener('close',()=>{lastTrigger?.focus();});
 dialog.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
 const open=()=>{lastTrigger=document.activeElement;if(anchor?.id==='crisBoardMenu'){anchor.hidden=true;document.querySelector('.cris-menu-toggle')?.setAttribute('aria-expanded','false');}if(!dialog.open)dialog.showModal();setMode('inbox');refresh().catch(e=>say(e.message,true));};button.onclick=open;
 function badge(){const count=notices.filter(n=>!read.has(n.id)).length,b=button.querySelector('b');b.textContent=count>99?'99+':count;b.hidden=!count;button.setAttribute('aria-label','Notificações'+(count?', '+count+' não lidas':''));button.classList.toggle('has-unread',count>0);document.title=(count?'('+count+') ':'')+baseTitle;}
 async function refresh(){if(!alive||loading)return;loading=true;const previous=JSON.stringify([notices,[...read].sort()]);try{const r=await client.from('operation_notices').select('id,payload,audience,created_at').eq('campaign_id',campaign).order('created_at',{ascending:false}).limit(100);if(r.error)throw r.error;const ids=r.data.map(n=>n.id);let reads=[];if(ids.length){const seen=await client.from('notice_reads').select('notice_id').eq('user_id',identity.userId).in('notice_id',ids);if(seen.error)throw seen.error;reads=seen.data;}if(!alive)return;read=new Set(reads.map(r=>r.notice_id));notices=r.data;if(!first){const newest=notices.find(n=>!known.has(n.id));if(newest)toast(newest);}for(const n of notices)known.add(n.id);first=false;badge();if(dialog.open&&mode==='inbox'&&previous!==JSON.stringify([notices,[...read].sort()]))renderInbox();}finally{loading=false;}}
 function toast(n){document.querySelector('.cris-notice-toast')?.remove();const t=document.createElement('section');t.className='cris-notice-toast';t.setAttribute('role','alert');t.innerHTML=icon+`<div class="notice-toast-content"><small>CRIS · ${n.audience==='self'?'TESTE PRIVADO':'NOVA OCORRÊNCIA'}</small><strong>${esc(n.payload.title)}</strong><p>${esc(n.payload.summary)}</p><div class="notice-toast-actions"><button type="button" data-open>Ver ocorrência</button><button type="button" data-dismiss>Dispensar</button></div></div>`;t.querySelector('[data-open]').onclick=()=>{t.remove();open();showNotice(n.id);};t.querySelector('[data-dismiss]').onclick=()=>t.remove();document.body.append(t);attention.playNotice(n.id).catch(()=>{});}
 function renderInbox(){body.innerHTML=`<div class="notices-list-head"><span>${notices.length?'Últimas ocorrências e comunicados':'Canal de operações'}</span><button type="button" data-refresh>Atualizar</button></div>${notices.length?'<div class="notices-list">'+notices.map(n=>`<button type="button" class="notice-list-item ${read.has(n.id)?'read':'unread'}" data-id="${n.id}"><div class="notice-list-icon">${icon}</div><span><small>${n.audience==='self'?'TESTE · SÓ VOCÊ':'CENTRAL DE OPERAÇÕES'}</small><strong>${esc(n.payload.title)}</strong><span>${esc(n.payload.summary)}</span></span><i aria-label="${read.has(n.id)?'Lida':'Não lida'}"></i></button>`).join('')+'</div>':'<div class="notices-empty">'+icon+'<h3>Nenhuma notificação por aqui</h3><p>Os avisos liberados pelo mestre ficam guardados neste canal, mesmo que você esteja fora do CRIS no momento do envio.</p></div>'}`;body.querySelector('[data-refresh]').onclick=()=>refresh().then(()=>say('Caixa de entrada atualizada.')).catch(e=>say(e.message,true));body.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>showNotice(b.dataset.id));}
 async function showNotice(id){if(!UUID.test(id))return;mode='detail';body.innerHTML='<p class="notices-empty">Abrindo ocorrência…</p>';try{let n=notices.find(x=>x.id===id);if(!n){const r=await client.from('operation_notices').select('id,payload,audience,created_at').eq('campaign_id',campaign).eq('id',id).maybeSingle();if(r.error)throw r.error;n=r.data;}if(!n)throw Error('Ocorrência indisponível para esta conta.');let imageURL='';if(n.payload.imagePath){const r=await client.storage.from('cris-notice-images').createSignedUrl(n.payload.imagePath,900);if(!r.error)imageURL=r.data.signedUrl;else say('A fotografia não pôde ser carregada. O relatório continua disponível.',true);}if(!alive||!dialog.open||mode!=='detail')return;body.innerHTML='<button type="button" class="notices-back">← Voltar às notificações</button>'+occurrenceMarkup(n.payload,{imageURL,test:n.audience==='self'});body.querySelector('.notices-back').onclick=()=>setMode('inbox');const r=await client.from('notice_reads').insert({notice_id:n.id,user_id:identity.userId,read_at:new Date().toISOString()});if(r.error&&r.error.code!=='23505')say('Relatório aberto. Não foi possível marcar como lido.',true);else{read.add(n.id);badge();document.querySelector('.cris-notice-toast')?.remove();}}catch(e){body.innerHTML='<div class="notices-empty">Não foi possível abrir este aviso.</div>';say(e.message,true);}}
 async function deviceStatus(){if(!('serviceWorker' in navigator)||!('PushManager'in window)||!('Notification'in window))return 'Este navegador não oferece notificações push. A caixa de entrada do CRIS continua funcionando.';if(Notification.permission==='denied')return 'As notificações estão bloqueadas nas configurações deste navegador.';const reg=await navigator.serviceWorker.getRegistration(ROOT.href),sub=await reg?.pushManager.getSubscription();return sub&&localStorage.getItem('cris:push-owner:'+ROOT.href)===identity.userId?'Notificações ativadas neste aparelho.':'Ative para receber avisos também com o CRIS fechado.';}
 let activating=null;
 function activate(){
  attention.unlock();if(activating)return activating;
  const stages={permission:'Aguardando permissão…',config:'Conectando ao CRIS…',key:'Verificando canal…',worker:'Preparando serviço…',push:'Cadastrando no navegador…',save:'Salvando aparelho no CRIS…'};
  activating=activatePushDevice({root:ROOT,userId:identity.userId,call,onStage:stage=>{const text=stages[stage];say(text);const label=setupBanner?.querySelector('[role=status]');if(label)label.textContent=text;}}).then(message=>{setupBanner?.remove();return message;}).finally(()=>{activating=null;});return activating;
 }
 async function deactivate(){const reg=await navigator.serviceWorker?.getRegistration(ROOT.href),sub=await reg?.pushManager.getSubscription();if(sub){try{await call('unsubscribe',{endpoint:sub.endpoint});}finally{await sub.unsubscribe();}}localStorage.removeItem('cris:push-owner:'+ROOT.href);}
 async function offerSetup(){
  if(anchor||setupDismissed||!alive)return;
  const supported='Notification'in window&&'PushManager'in window&&'serviceWorker'in navigator;
  let subscribed=false;try{const reg=await navigator.serviceWorker?.getRegistration(ROOT.href);subscribed=!!await reg?.pushManager.getSubscription()&&localStorage.getItem('cris:push-owner:'+ROOT.href)===identity.userId;}catch{}
  if(!alive||setupDismissed||(supported&&Notification.permission==='granted'&&subscribed))return;
  const blocked=supported&&Notification.permission==='denied';setupBanner?.remove();setupBanner=document.createElement('section');setupBanner.className='cris-notice-setup';setupBanner.setAttribute('aria-label','Ativar avisos do CRIS');
  setupBanner.innerHTML=icon+`<div><strong>${blocked?'Libere os avisos da central':'Ative os avisos da central'}</strong><p>${blocked?'As notificações estão bloqueadas neste navegador. Permita os avisos nas configurações deste site.':!supported?'Os avisos continuam disponíveis no CRIS. Confira as opções de recebimento para este navegador.':'Receba as ocorrências neste aparelho. No notebook, o CRIS também pode emitir um sinal sonoro enquanto a página estiver aberta.'}</p><span role="status"></span></div><div class="notice-setup-actions"><button type="button" data-enable>${blocked||!supported?'Ver opções':'Ativar notificações'}</button><button type="button" data-options hidden>Ver orientações</button><button type="button" data-later>Depois</button></div>`;
  (document.querySelector('#system .content')||document.body).prepend(setupBanner);
  const banner=setupBanner;banner.querySelector('[data-options]').onclick=()=>{open();setMode('device');};banner.querySelector('[data-later]').onclick=()=>{setupDismissed=true;banner.remove();};
  banner.querySelector('[data-enable]').onclick=async e=>{if(blocked||!supported){open();setMode('device');return;}const button=e.currentTarget;button.disabled=true;try{await activate();}catch(error){banner.querySelector('[role=status]').textContent=error.message;banner.querySelector('[data-options]').hidden=false;button.textContent='Tentar novamente';}finally{button.disabled=false;}};
 }
 async function renderDevice(){body.innerHTML=`<section class="notice-device">${icon}<h3>Notificações neste aparelho</h3><p data-device-status>Verificando…</p><button type="button" data-enable>Ativar notificações</button><button type="button" data-disable>Desativar neste aparelho</button><small>O som e a vibração da notificação do sistema seguem as configurações do celular ou computador. Se estiverem bloqueados, permita os avisos nas configurações deste site e confira as permissões do navegador no aparelho.</small><details class="notice-push-help"><summary>Não consigo ativar neste aparelho</summary><p>Abra o endereço do CRIS diretamente no navegador, fora de aplicativos de mensagens. Confira as permissões de notificação do site e do navegador no celular. Se o serviço continuar indisponível, atualize o navegador e tente outra rede. No iPhone, abra pelo ícone adicionado à Tela de Início.</p><p>Enquanto isso, mantenha o CRIS aberto: as ocorrências aparecem no sino e os novos avisos ficam na tela. Você também pode ativar o sinal sonoro abaixo.</p></details><hr><h4>Sinal sonoro do CRIS</h4><label class="notice-sound-toggle"><input type="checkbox" data-sound ${attention.enabled?'checked':''}><span>Tocar o sinal da central com esta página aberta</span></label><button type="button" data-sound-test>Ouvir sinal</button><small>Um sinal curto de rádio e terminal, pensado para a mesa. Um clique na página libera o áudio quando o navegador permite. Fora do CRIS aberto, vale o som de notificação do sistema.</small>${identity.isMaster?'<hr><h4>Teste de conexão</h4><p>Verifica o recebimento com uma mensagem genérica só para você. Para testar a ocorrência completa, use o botão de envio privado em Nova ocorrência.</p><button type="button" data-test>Testar conexão neste canal</button>':''}</section>`;
  const label=body.querySelector('[data-device-status]');deviceStatus().then(t=>{if(label.isConnected)label.textContent=t;}).catch(()=>{if(label.isConnected)label.textContent='Ative as notificações para verificar este aparelho.';});
  body.querySelector('[data-enable]').onclick=e=>busy(e.currentTarget,async()=>{const msg=await activate();say(msg);label.textContent=msg;});body.querySelector('[data-disable]').onclick=e=>busy(e.currentTarget,async()=>{await deactivate();label.textContent='Desativadas neste aparelho.';say('Sua caixa de entrada continua disponível.');offerSetup();});
  body.querySelector('[data-sound]').onchange=async e=>{attention.setEnabled(e.target.checked);if(e.target.checked)await attention.unlock();say(e.target.checked?'Sinal sonoro do CRIS ativado nesta página.':'Sinal sonoro silenciado.');};
  body.querySelector('[data-sound-test]').onclick=e=>busy(e.currentTarget,async()=>{await attention.test();body.querySelector('[data-sound]').checked=true;say('Sinal da central reproduzido. Ajuste o volume do aparelho se necessário.');});
  body.querySelector('[data-test]')?.addEventListener('click',e=>busy(e.currentTarget,()=>publishTest()));
 }
 async function busy(b,fn){b.disabled=true;try{await fn();}catch(e){say(e.message,true);}finally{b.disabled=false;}}
 async function publishTest(kind='connection'){const payload=kind==='draft'?normalizeNotice(draft,campaign):{};const result=await call('publish',{campaignId:campaign,noticeId:newId(),audience:'self',testKind:kind,payload});say((kind==='draft'?'Sua ocorrência completa foi enviada somente para você. ':'Teste de conexão salvo somente para você. ')+deliveryText(result));await refresh();}
 function deliveryText(r){return r.devices?`${r.pushAccepted} envio(s) aceito(s) pelo serviço push${r.pushFailed?'; '+r.pushFailed+' falharam':''}.`:'Nenhum aparelho ativado ainda. O aviso está disponível na caixa de entrada.';}
 function saveDraft(){requestId=newId();try{localStorage.setItem(DRAFT+identity.userId+':'+campaign,JSON.stringify({...draft,_requestId:requestId}));}catch{}}
 async function renderCompose(){const field=(label,name,{type='text',rows,max,optional=false}={})=>`<label><span>${label}</span>${rows?`<textarea name="${name}" rows="${rows}" maxlength="${max||5000}" ${optional?'':'required'}>${esc(draft[name])}</textarea>`:`<input name="${name}" type="${type}" maxlength="${max||160}" value="${esc(draft[name])}" ${(optional||['date','location','imageCaption','occurrenceTime'].includes(name))?'':'required'}>`}</label>`;
  body.innerHTML=`<div class="notice-compose-top"><p><strong>Rascunho privado</strong> · Nada desta tela foi enviado aos jogadores.</p><button type="button" data-preview-toggle>Ver prévia</button></div><div class="notice-compose"><form class="notice-compose-form">${field('Título da notificação','title',{max:120})}${field('Resumo que aparece no celular','summary',{rows:2,max:300})}<div class="notice-form-grid">${field('Número da ocorrência','code',{max:32})}${field('Data na campanha','date',{type:'date'})}</div>${field('Horário da ocorrência · Paris','occurrenceTime',{type:'time',optional:true})}<p class="notice-field-hint">Horário local de Paris, no formato HH:mm. Deixe vazio se estiver a confirmar.</p>${field('Local · cidade e país','location')}${field('Endereço da ocorrência','address',{rows:2,max:500,optional:true})}<div class="notice-form-grid">${field('Natureza','nature',{max:100})}${field('Situação do local','situation',{max:100})}</div>${field('Informações preliminares','preliminary',{rows:5})}${field('Orientação operacional','guidance',{rows:3,max:3000})}<label><span>Fotografia da ocorrência · opcional</span><input type="file" accept="image/png,image/jpeg,image/webp" data-photo><small>A foto é preparada em rascunho. Só fica acessível aos jogadores após o envio real.</small></label><button type="button" data-remove-photo ${draft.imagePath?'':'hidden'}>Remover fotografia</button>${field('Legenda / fonte da imagem','imageCaption',{max:240})}<div class="notice-send-box"><span>DESTINATÁRIOS</span><strong>Confira a ocorrência no seu aparelho</strong><p>O envio privado inclui o título, o texto e a foto desta ocorrência, somente para a sua conta. A equipe só recebe após revisar e confirmar o envio real.</p><button type="button" data-test>Enviar esta ocorrência só para mim</button><button type="submit" class="notice-publish">Revisar envio à equipe →</button></div></form><aside class="notice-preview"><span class="notice-preview-label">PRÉVIA · VISÍVEL SOMENTE PARA VOCÊ</span><div class="notice-phone"><small>CRIS · CENTRAL DE OPERAÇÕES · Agora</small><strong data-preview-title></strong><p data-preview-summary></p></div><div data-preview-report></div></aside></div>`;
  const form=body.querySelector('form'),preview=body.querySelector('[data-preview-report]');
  const renderPreview=()=>{body.querySelector('[data-preview-title]').textContent=draft.title;body.querySelector('[data-preview-summary]').textContent=draft.summary;preview.innerHTML=occurrenceMarkup(draft,{imageURL:photo});};
  form.addEventListener('input',e=>{if(!(e.target.name in draft))return;draft[e.target.name]=e.target.value;saveDraft();renderPreview();});
  body.querySelector('[data-preview-toggle]').onclick=e=>{const shown=body.classList.toggle('notice-preview-open');e.currentTarget.textContent=shown?'Voltar à edição':'Ver prévia';};
  form.querySelector('[data-test]').onclick=e=>{if(!form.reportValidity())return;busy(e.currentTarget,()=>publishTest('draft'));};
  const remove=form.querySelector('[data-remove-photo]');remove.onclick=()=>{draft.imagePath='';photo='';saveDraft();remove.hidden=true;form.querySelector('[data-photo]').value='';renderPreview();};
  form.querySelector('[data-photo]').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;await busy(form.querySelector('[data-test]'),async()=>{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024)throw Error('Use PNG, JPG ou WebP de até 15 MB.');const url=URL.createObjectURL(file),image=new Image();let blob;try{image.src=url;await image.decode();const scale=Math.min(1,2000/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.9));}finally{URL.revokeObjectURL(url);}if(!blob||blob.size>3*1024*1024)throw Error('A fotografia ficou muito grande. Reduza e tente novamente.');const path=campaign+'/'+newId()+'.webp';const r=await client.storage.from('cris-notice-images').upload(path,blob,{contentType:blob.type,upsert:false});if(r.error)throw r.error;const signed=await client.storage.from('cris-notice-images').createSignedUrl(path,900);if(signed.error)throw signed.error;draft.imagePath=path;photo=signed.data.signedUrl;remove.hidden=false;saveDraft();renderPreview();say('Fotografia preparada. Ainda não foi liberada aos jogadores.');});};
  form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;try{normalizeNotice(draft,campaign);}catch(error){say(error.message,true);return;}renderConfirm();};
  renderPreview();if(draft.imagePath&&!photo){const r=await client.storage.from('cris-notice-images').createSignedUrl(draft.imagePath,900);if(!r.error&&preview.isConnected){photo=r.data.signedUrl;renderPreview();}}
 }
 function renderConfirm(){mode='confirm';body.classList.remove('notice-preview-open');body.innerHTML=`<div class="notice-confirm"><span>ENVIO REAL À EQUIPE</span><h3>Publicar esta ocorrência?</h3><p>Todos os integrantes atuais da campanha poderão abrir o relatório. Quem ativou as notificações também receberá o aviso nos seus aparelhos.</p><div class="notice-phone"><small>CRIS · CENTRAL DE OPERAÇÕES</small><strong>${esc(draft.title)}</strong><p>${esc(draft.summary)}</p></div><p>Depois do envio, a mensagem pode já ter aparecido nos aparelhos dos jogadores.</p><div><button type="button" data-back>Voltar ao rascunho</button><button type="button" class="notice-publish" data-send>Enviar agora à equipe</button></div></div>`;body.querySelector('[data-back]').onclick=()=>setMode('compose');body.querySelector('[data-send]').onclick=e=>busy(e.currentTarget,async()=>{sending=true;say('Publicando ocorrência…');try{const result=await call('publish',{campaignId:campaign,noticeId:requestId,audience:'campaign',payload:normalizeNotice(draft,campaign)});say('Ocorrência publicada para '+result.recipients+' integrante(s). '+deliveryText(result));await refresh();sending=false;mode='inbox';renderInbox();requestId=newId();}finally{sending=false;}});}
 const visibility=()=>{if(!document.hidden)refresh().catch(()=>{});};document.addEventListener('visibilitychange',visibility);window.addEventListener('online',visibility);const timer=setInterval(()=>{if(!document.hidden)refresh().catch(()=>{});},20000);
 const channel=client.channel('cris-notices:'+identity.userId+':'+campaign).on('postgres_changes',{event:'INSERT',schema:'public',table:'operation_notices',filter:'campaign_id=eq.'+campaign},()=>refresh().catch(()=>{})).subscribe();
 if('serviceWorker'in navigator)navigator.serviceWorker.getRegistration(ROOT.href).then(reg=>reg?.update()).catch(()=>{});
 const logout=async()=>{await deactivate().catch(()=>{});alive=false;attention.dispose();setupBanner?.remove();document.querySelector('.cris-notice-toast')?.remove();document.title=baseTitle;document.removeEventListener('pointerdown',unlockAudio,true);document.removeEventListener('keydown',unlockAudio,true);clearInterval(timer);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('online',visibility);await client.removeChannel(channel);dialog.remove();button.remove();};
 window.CRIS_NOTIFICATIONS={open,beforeLogout:logout};
 offerSetup().catch(()=>{});
 try{await refresh();const id=new URL(location.href).searchParams.get('notice');if(UUID.test(id||'')){open();await showNotice(id);}}catch(e){say('O canal não pôde ser atualizado. '+e.message,true);}
 return window.CRIS_NOTIFICATIONS;
}
